import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Fetch Mail (Gmail)","description":"","frontmatter":{"prev":{"text":"2Captcha","link":"/documentation/field-types/captcha-solution/2captcha"},"next":{"text":"Fetch Single Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/fetch-single-mail-gmail"}},"headers":[],"relativePath":"documentation/field-types/google-service-gmail/fetch-mail-gmail.md","filePath":"documentation/field-types/google-service-gmail/fetch-mail-gmail.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/google-service-gmail/fetch-mail-gmail.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fetch-mail-gmail" tabindex="-1">Fetch Mail (Gmail) <a class="header-anchor" href="#fetch-mail-gmail" aria-label="Permalink to “Fetch Mail (Gmail)”">​</a></h1><p>Retrieve and filter multiple emails from your Gmail account using search queries, labels, regex extractors, and automated retry mechanisms.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>Fetch Mail (Gmail)</strong> field type connects to the Google Gmail API using your authorized Google account to harvest email data into automation workflows. It allows extracting email bodies, subject lines, senders, recipients, and tokens (like OTPs or verification URLs) with full regex support.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Google Service Account</strong></td><td>Dropdown</td><td>Logged-in Google account with Gmail permissions.</td><td>Yes</td></tr><tr><td><strong>Mail Parts</strong></td><td>Input Tags</td><td>Specific email parts to extract (<code>body</code>, <code>subject</code>, <code>from</code>, <code>snippet</code>, <code>to</code>).</td><td>Yes</td></tr><tr><td><strong>Enable Max Results</strong></td><td>Toggle Switch</td><td>Limit the number of matching emails returned.</td><td>No</td></tr><tr><td><strong>Max Results Count</strong></td><td>Number Input</td><td>Maximum count of messages to fetch (e.g., <code>5</code>, <code>10</code>, <code>50</code>).</td><td>When limit enabled</td></tr><tr><td><strong>Use Gmail Labels</strong></td><td>Toggle Switch</td><td>Filter search specifically within chosen Gmail labels.</td><td>No</td></tr><tr><td><strong>Gmail Label IDs</strong></td><td>Multi-Select</td><td>Select labels to scope the search (e.g., <code>INBOX</code>, <code>SPAM</code>, <code>UNREAD</code>).</td><td>When labels enabled</td></tr><tr><td><strong>Include Spam/Trash</strong></td><td>Toggle Switch</td><td>Includes messages located in Spam or Trash folders.</td><td>No</td></tr><tr><td><strong>Enable Retry on Failure</strong></td><td>Toggle Switch</td><td>Re-attempts the API query if network errors occur.</td><td>No</td></tr><tr><td><strong>Max Retries (Failure)</strong></td><td>Number Input</td><td>Maximum retry attempts for failed requests.</td><td>When retry enabled</td></tr><tr><td><strong>Retry Until Mail Received</strong></td><td>Toggle Switch</td><td>Polls repeatedly until an email matching search criteria arrives.</td><td>No</td></tr><tr><td><strong>Max Retries (Until Received)</strong></td><td>Number Input</td><td>Number of polling cycles to wait for new emails.</td><td>When polling enabled</td></tr><tr><td><strong>Timeout</strong></td><td>Number Input</td><td>Wait timeout in seconds between polling cycles.</td><td>No</td></tr><tr><td><strong>Enable Regex Filter</strong></td><td>Toggle Switch</td><td>Applies regular expressions to extract specific patterns from email content.</td><td>No</td></tr><tr><td><strong>Regular Expression</strong></td><td>Text Input</td><td>Regex pattern to capture tokens (e.g. <code>\\b\\d{6}\\b</code> for 6-digit OTPs).</td><td>When regex enabled</td></tr><tr><td><strong>Regex Replace</strong></td><td>Text Input</td><td>Optional replacement string for matched regex patterns.</td><td>No</td></tr><tr><td><strong>Remove UNREAD Label</strong></td><td>Toggle Switch</td><td>Automatically marks retrieved emails as read to prevent reprocessing.</td><td>No</td></tr><tr><td><strong>Search Query</strong></td><td>Default Value</td><td>Standard Gmail search operators to filter messages.</td><td>No</td></tr></tbody></table><hr><h2 id="option-details" tabindex="-1">Detailed Settings Breakdown <a class="header-anchor" href="#option-details" aria-label="Permalink to “Detailed Settings Breakdown”">​</a></h2><h3 id="google-service-account" tabindex="-1">Google Service Account <a class="header-anchor" href="#google-service-account" aria-label="Permalink to “Google Service Account”">​</a></h3><p>Select the authorized Google identity registered under <a href="/documentation/services/google-service.html">Google Service</a>. Ensure the account holds valid OAuth2 permissions to read Gmail messages.</p><h3 id="mail-parts" tabindex="-1">Mail Parts <a class="header-anchor" href="#mail-parts" aria-label="Permalink to “Mail Parts”">​</a></h3><p>Specify which components of the message to parse:</p><ul><li><code>body</code>: Plain text or HTML email body.</li><li><code>subject</code>: Email subject header.</li><li><code>from</code>: Sender name and address (<code>sender@domain.com</code>).</li><li><code>to</code>: Recipient address(es).</li><li><code>snippet</code>: Short preview text snippet generated by Gmail.</li></ul><h3 id="polling-for-incoming-emails" tabindex="-1">Polling for Incoming Emails <a class="header-anchor" href="#polling-for-incoming-emails" aria-label="Permalink to “Polling for Incoming Emails”">​</a></h3><p>When an automated form triggers an email verification code:</p><ol><li>Enable <strong>Retry Until Mail Received</strong>.</li><li>Set <strong>Max Retries</strong> (e.g., <code>10</code>).</li><li>Set <strong>Timeout</strong> (e.g., <code>10</code> seconds).</li><li>The extension will poll Gmail every 10 seconds (up to 10 times) until the message arrives.</li></ol><h3 id="regex-extraction" tabindex="-1">Regex Extraction <a class="header-anchor" href="#regex-extraction" aria-label="Permalink to “Regex Extraction”">​</a></h3><p>Extract specific text fragments from the email body:</p><ul><li><strong>6-Digit Verification Code</strong>: <code>\\b\\d{6}\\b</code></li><li><strong>Confirmation Link</strong>: <code>https://example\\.com/verify\\?token=[a-zA-Z0-9_-]+</code></li><li><strong>Invoice Number</strong>: <code>INV-\\d{5,8}</code></li></ul><h3 id="mark-as-read-remove-unread-label" tabindex="-1">Mark as Read (<code>Remove UNREAD Label</code>) <a class="header-anchor" href="#mark-as-read-remove-unread-label" aria-label="Permalink to “Mark as Read (Remove UNREAD Label)”">​</a></h3><p>Enable <strong>Remove UNREAD Label</strong> to strip the <code>UNREAD</code> badge upon successful retrieval. This ensures subsequent loop iterations or forms do not read the same verification message twice.</p><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-fetching-unread-verification-code" tabindex="-1">Example 1: Fetching Unread Verification Code <a class="header-anchor" href="#example-1-fetching-unread-verification-code" aria-label="Permalink to “Example 1: Fetching Unread Verification Code”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: user@example.com</span></span>
<span class="line"><span>Mail Parts: body</span></span>
<span class="line"><span>Retry Until Mail Received: ON</span></span>
<span class="line"><span>Max Retries (Until Received): 8</span></span>
<span class="line"><span>Timeout: 5 seconds</span></span>
<span class="line"><span>Enable Regex Filter: ON</span></span>
<span class="line"><span>Regular Expression: \\b\\d{6}\\b</span></span>
<span class="line"><span>Remove UNREAD Label: ON</span></span>
<span class="line"><span>Search Query: from:auth@service.com is:unread</span></span></code></pre></div><h3 id="example-2-extracting-latest-billing-report" tabindex="-1">Example 2: Extracting Latest Billing Report <a class="header-anchor" href="#example-2-extracting-latest-billing-report" aria-label="Permalink to “Example 2: Extracting Latest Billing Report”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: billing@company.com</span></span>
<span class="line"><span>Mail Parts: subject, snippet</span></span>
<span class="line"><span>Enable Max Results: ON</span></span>
<span class="line"><span>Max Results Count: 1</span></span>
<span class="line"><span>Search Query: subject:&quot;Monthly Invoice&quot; after:2025/01/01</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><h3 id="do-s" tabindex="-1">Do&#39;s <a class="header-anchor" href="#do-s" aria-label="Permalink to “Do&#39;s”">​</a></h3><ul><li><strong>Use Precise Search Queries</strong>: Scope searches with <code>from:</code>, <code>subject:</code>, and <code>newer_than:1d</code> to minimize API latency.</li><li><strong>Mark Processed Emails as Read</strong>: Prevent duplicate data processing by enabling <strong>Remove UNREAD Label</strong>.</li><li><strong>Set Realistic Polling Timeouts</strong>: Give external email delivery servers at least 30–60 seconds to deliver OTP messages.</li></ul><h3 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to “Don&#39;ts”">​</a></h3><ul><li><strong>Do Not Fetch Unbounded Queries</strong>: Avoid broad queries without <code>is:unread</code> or date boundaries.</li><li><strong>Do Not Set Infinite Retries</strong>: Limit polling to a reasonable count (e.g., 6–10 attempts).</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>No emails found</strong></td><td>Search query too restrictive or email delayed</td><td>Verify search parameters manually in Gmail web interface. Increase retry timeout.</td></tr><tr><td><strong>Permission denied (403)</strong></td><td>Missing Gmail API scope</td><td>Re-authenticate Google account under <a href="/documentation/services/google-service.html">Google Service</a>.</td></tr><tr><td><strong>Regex returns empty</strong></td><td>Pattern does not match email body formatting</td><td>Test regex against the actual raw email body text.</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/globe.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/gmail-api-search-queries.html">Gmail API Search Queries Guide</a></li><li><img src="/svg/chat.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/fetch-single-mail-gmail.html">Fetch Single Mail (Gmail)</a></li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/send-mail-gmail.html">Send Mail (Gmail)</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/services/google-service.html">Google Service Account Setup</a></li></ul>`,41)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};